import json
from pathlib import Path

OUTBOX = Path(__file__).resolve().parent / "outbox"

def status():
    return {"status": "ok", "module": __name__}

def run(config: dict):
    OUTBOX.mkdir(parents=True, exist_ok=True)
    flow = {"flow": True}
    job = {"job": True}
    summary = {"summary": True}
    (OUTBOX / "flowspec.json").write_text(json.dumps(flow), encoding="utf-8")
    (OUTBOX / "jobspec.json").write_text(json.dumps(job), encoding="utf-8")
    (OUTBOX / "department_summary.json").write_text(json.dumps(summary), encoding="utf-8")
    return {"flow_spec": flow, "job_spec": job, "department_summary": summary}
